   442→		t.Error("second checkpoint with identical content should be skipped")
   443→	}
   444→	if result2.CommitHash != result1.CommitHash {
   445→		t.Errorf("skipped checkpoint should return previous commit hash, got %s, want %s",
   446→			result2.CommitHash, result1.CommitHash)
   447→	}
   448→
   449→	// Modify the file and create another checkpoint - should NOT be skipped
   450→	if err := os.WriteFile(testFile, []byte("package main\n\nfunc main() {}\n"), 0o644); err != nil {
   451→		t.Fatalf("failed to modify test file: %v", err)
   452→	}
   453→
   454→	result3, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   455→		SessionID:         "test-session",
   456→		BaseCommit:        baseCommit,
   457→		ModifiedFiles:     []string{"test.go"},
   458→		MetadataDir:       ".entire/metadata/test-session",
   459→		MetadataDirAbs:    metadataDir,
   460→		CommitMessage:     "Checkpoint 3",
   461→		AuthorName:        "Test",
   462→		AuthorEmail:       "test@test.com",
   463→		IsFirstCheckpoint: false,
   464→	})
   465→	if err != nil {
   466→		t.Fatalf("WriteTemporary() third call error = %v", err)
   467→	}
   468→	if result3.Skipped {
   469→		t.Error("third checkpoint with modified content should NOT be skipped")
   470→	}
   471→	if result3.CommitHash == result1.CommitHash {
   472→		t.Error("third checkpoint should have a different commit hash than first")
   473→	}
   474→}
