package strategy

import (
	"context"
	"fmt"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

// Shadow strategy session state methods.
// Uses session.StateStore for persistence.

// loadSessionState loads session state using the StateStore.
func (s *ManualCommitStrategy) loadSessionState(sessionID string) (*SessionState, error) {
	store, err := s.getStateStore()
	if err != nil {
		return nil, err
	}
	state, err := store.Load(context.Background(), sessionID)
	if err != nil {
		return nil, fmt.Errorf("failed to load session state: %w", err)
	}
	return sessionStateToStrategy(state), nil
}

// saveSessionState saves session state using the StateStore.
func (s *ManualCommitStrategy) saveSessionState(state *SessionState) error {
	store, err := s.getStateStore()
	if err != nil {
		return err
	}
	if err := store.Save(context.Background(), sessionStateFromStrategy(state)); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}
	return nil
}

// clearSessionState clears session state using the StateStore.
func (s *ManualCommitStrategy) clearSessionState(sessionID string) error {
	store, err := s.getStateStore()
	if err != nil {
		return err
	}
	if err := store.Clear(context.Background(), sessionID); err != nil {
		return fmt.Errorf("failed to clear session state: %w", err)
	}
	return nil
}

// listAllSessionStates returns all active session states.
// It filters out orphaned sessions whose shadow branch no longer exists.
func (s *ManualCommitStrategy) listAllSessionStates() ([]*SessionState, error) {
	store, err := s.getStateStore()
	if err != nil {
		return nil, fmt.Errorf("failed to get state store: %w", err)
	}

	sessionStates, err := store.List(context.Background())
	if err != nil {
		return nil, fmt.Errorf("failed to list session states: %w", err)
	}

	if len(sessionStates) == 0 {
		return nil, nil
	}

	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	var states []*SessionState
	for _, sessionState := range sessionStates {
		state := sessionStateToStrategy(sessionState)

		// Skip and cleanup orphaned sessions whose shadow branch no longer exists
		// Only cleanup if the session has created checkpoints (CheckpointCount > 0)
		// AND has no LastCheckpointID (not recently condensed)
		// Sessions with LastCheckpointID are valid - they were condensed and the shadow
		// branch was intentionally deleted. Keep them for LastCheckpointID reuse.
		shadowBranch := getShadowBranchNameForCommit(state.BaseCommit)
		refName := plumbing.NewBranchReferenceName(shadowBranch)
		if _, err := repo.Reference(refName, true); err != nil {
			// Shadow branch doesn't exist
			// Only cleanup if session has checkpoints AND no LastCheckpointID
			// Sessions with LastCheckpointID should be kept for checkpoint reuse
			if state.CheckpointCount > 0 && state.LastCheckpointID == "" {
				// Clear the orphaned session state (best-effort, don't fail listing)
				//nolint:errcheck,gosec // G104: Cleanup is best-effort, shouldn't fail the list operation
				store.Clear(context.Background(), state.SessionID)
				continue
			}
			// Keep sessions with LastCheckpointID or no checkpoints yet
		}

		states = append(states, state)
	}
	return states, nil
}

// findSessionsForWorktree finds all sessions for the given worktree path.
func (s *ManualCommitStrategy) findSessionsForWorktree(worktreePath string) ([]*SessionState, error) {
	allStates, err := s.listAllSessionStates()
	if err != nil {
		return nil, err
	}

	var matching []*SessionState
	for _, state := range allStates {
		if state.WorktreePath == worktreePath {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// findSessionsForCommit finds all sessions where base_commit matches the given SHA.
func (s *ManualCommitStrategy) findSessionsForCommit(baseCommitSHA string) ([]*SessionState, error) {
	allStates, err := s.listAllSessionStates()
	if err != nil {
		return nil, err
	}

	var matching []*SessionState
	for _, state := range allStates {
		if state.BaseCommit == baseCommitSHA {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// FindSessionsForCommit is the exported version of findSessionsForCommit.
// Used by the rewind reset command to find sessions to clean up.
func (s *ManualCommitStrategy) FindSessionsForCommit(baseCommitSHA string) ([]*SessionState, error) {
	return s.findSessionsForCommit(baseCommitSHA)
}

// ClearSessionState is the exported version of clearSessionState.
// Used by the rewind reset command to clean up session state files.
func (s *ManualCommitStrategy) ClearSessionState(sessionID string) error {
	return s.clearSessionState(sessionID)
}

// HasOtherActiveSessionsWithCheckpoints checks if there are other active sessions
// from the SAME worktree (different from currentSessionID) that have created checkpoints
// on the SAME base commit (current HEAD). This is used to detect concurrent sessions
// in different terminals but same directory.
// Returns the first found session with CheckpointCount > 0, or nil if none found.
func (s *ManualCommitStrategy) HasOtherActiveSessionsWithCheckpoints(currentSessionID string) (*SessionState, error) {
	currentWorktree, err := GetWorktreePath()
	if err != nil {
		return nil, err
	}

	// Get current HEAD to compare with session base commits
	repo, err := OpenRepository()
	if err != nil {
		return nil, err
	}
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}
	currentHead := head.Hash().String()

	allStates, err := s.listAllSessionStates()
	if err != nil {
		return nil, err
	}

	for _, state := range allStates {
		// Only consider sessions from the same worktree with checkpoints
		// AND based on the same commit (current HEAD)
		// Sessions from different base commits are independent and shouldn't trigger warning
		if state.SessionID != currentSessionID &&
			state.WorktreePath == currentWorktree &&
			state.CheckpointCount > 0 &&
			state.BaseCommit == currentHead {
			return state, nil
		}
	}
	return nil, nil //nolint:nilnil // nil,nil indicates no other session found (expected case)
}

// initializeSession creates a new session state or updates a partial one.
// A partial state may exist if the concurrent session warning was shown.
// agentType is the human-readable name of the agent (e.g., "Claude Code").
// transcriptPath is the path to the live transcript file (for mid-session commit detection).
func (s *ManualCommitStrategy) initializeSession(repo *git.Repository, sessionID string, agentType agent.AgentType, transcriptPath string) (*SessionState, error) {
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	worktreePath, err := GetWorktreePath()
	if err != nil {
		return nil, fmt.Errorf("failed to get worktree path: %w", err)
	}

	// Capture untracked files at session start to preserve them during rewind
	untrackedFiles, err := collectUntrackedFiles()
	if err != nil {
		// Non-fatal: continue even if we can't collect untracked files
		untrackedFiles = nil
	}

	// Check if a partial state exists (from concurrent warning)
	// Ignore errors - we just want to preserve the warning flag if present
	existingState, loadErr := s.loadSessionState(sessionID)
	var concurrentWarningShown bool
	if loadErr == nil && existingState != nil {
		concurrentWarningShown = existingState.ConcurrentWarningShown
	}

	state := &SessionState{
		SessionID:              sessionID,
		BaseCommit:             head.Hash().String(),
		WorktreePath:           worktreePath,
		StartedAt:              time.Now(),
		CheckpointCount:        0,
		UntrackedFilesAtStart:  untrackedFiles,
		ConcurrentWarningShown: concurrentWarningShown, // Preserve the warning flag
		AgentType:              agentType,
		TranscriptPath:         transcriptPath,
	}

	if err := s.saveSessionState(state); err != nil {
		return nil, err
	}

	return state, nil
}

// getShadowBranchNameForCommit returns the shadow branch name for the given base commit.
func getShadowBranchNameForCommit(baseCommit string) string {
	if len(baseCommit) >= checkpoint.ShadowBranchHashLength {
		return shadowBranchPrefix + baseCommit[:checkpoint.ShadowBranchHashLength]
	}
	return shadowBranchPrefix + baseCommit
}

package strategy

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sort"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

// SaveChanges saves a checkpoint to the shadow branch.
// Uses checkpoint.GitStore.WriteTemporary for git operations.
func (s *ManualCommitStrategy) SaveChanges(ctx SaveContext) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Extract session ID from metadata dir
	sessionID := filepath.Base(ctx.MetadataDir)

	// Load or initialize session state
	state, err := s.loadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session state: %w", err)
	}
	// Initialize if state is nil OR BaseCommit is empty (can happen with partial state from warnings)
	if state == nil || state.BaseCommit == "" {
		// Preserve existing AgentType if we have a partial state, otherwise use default
		agentType := DefaultAgentType
		if state != nil && state.AgentType != "" {
			agentType = state.AgentType
		}
		state, err = s.initializeSession(repo, sessionID, agentType, "") // No transcript path in fallback
		if err != nil {
			return fmt.Errorf("failed to initialize session: %w", err)
		}
	}

	// Get checkpoint store
	store, err := s.getCheckpointStore()
	if err != nil {
		return fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Check if shadow branch exists to report whether we created it
	shadowBranchName := checkpoint.ShadowBranchNameForCommit(state.BaseCommit)
	branchExisted := store.ShadowBranchExists(state.BaseCommit)

	// Use the pending attribution calculated at prompt start (in InitializeSession)
	// This was calculated BEFORE the agent made changes, so it accurately captures user edits
	var promptAttr PromptAttribution
	if state.PendingPromptAttribution != nil {
		promptAttr = *state.PendingPromptAttribution
		state.PendingPromptAttribution = nil // Clear after use
	} else {
		// No pending attribution (e.g., first checkpoint or session initialized without it)
		promptAttr = PromptAttribution{CheckpointNumber: state.CheckpointCount + 1}
	}

	// Log the prompt attribution for debugging
	attrLogCtx := logging.WithComponent(context.Background(), "attribution")
	logging.Debug(attrLogCtx, "prompt attribution at checkpoint save",
		slog.Int("checkpoint_number", promptAttr.CheckpointNumber),
		slog.Int("user_added", promptAttr.UserLinesAdded),
		slog.Int("user_removed", promptAttr.UserLinesRemoved),
		slog.Int("agent_added", promptAttr.AgentLinesAdded),
		slog.Int("agent_removed", promptAttr.AgentLinesRemoved),
		slog.String("session_id", sessionID))

	// Use WriteTemporary to create the checkpoint
	isFirstCheckpointOfSession := state.CheckpointCount == 0
	result, err := store.WriteTemporary(context.Background(), checkpoint.WriteTemporaryOptions{
		SessionID:         sessionID,
		BaseCommit:        state.BaseCommit,
		ModifiedFiles:     ctx.ModifiedFiles,
		NewFiles:          ctx.NewFiles,
		DeletedFiles:      ctx.DeletedFiles,
		MetadataDir:       ctx.MetadataDir,
		MetadataDirAbs:    ctx.MetadataDirAbs,
		CommitMessage:     ctx.CommitMessage,
		AuthorName:        ctx.AuthorName,
		AuthorEmail:       ctx.AuthorEmail,
		IsFirstCheckpoint: isFirstCheckpointOfSession,
	})
	if err != nil {
		return fmt.Errorf("failed to write temporary checkpoint: %w", err)
	}

	// If checkpoint was skipped due to deduplication (no changes), return early
	if result.Skipped {
		logCtx := logging.WithComponent(context.Background(), "checkpoint")
		logging.Info(logCtx, "checkpoint skipped (no changes)",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_type", "session"),
			slog.Int("checkpoint_count", state.CheckpointCount),
			slog.String("shadow_branch", shadowBranchName),
		)
		fmt.Fprintf(os.Stderr, "Skipped checkpoint (no changes since last checkpoint)\n")
		return nil
	}

	// Update session state
	state.CheckpointCount++

	// Store the prompt attribution we calculated before saving
	state.PromptAttributions = append(state.PromptAttributions, promptAttr)

	// Track touched files (modified, new, and deleted)
	state.FilesTouched = mergeFilesTouched(state.FilesTouched, ctx.ModifiedFiles, ctx.NewFiles, ctx.DeletedFiles)

	// On first checkpoint, store the initial transcript position
	if isFirstCheckpointOfSession {
		state.TranscriptLinesAtStart = ctx.TranscriptLinesAtStart
		state.TranscriptIdentifierAtStart = ctx.TranscriptIdentifierAtStart
	}

	// Accumulate token usage
	if ctx.TokenUsage != nil {
		state.TokenUsage = accumulateTokenUsage(state.TokenUsage, ctx.TokenUsage)
	}

	// Save updated state
	if err := s.saveSessionState(state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}

	if !branchExisted {
		fmt.Fprintf(os.Stderr, "Created shadow branch '%s' and committed changes\n", shadowBranchName)
	} else {
		fmt.Fprintf(os.Stderr, "Committed changes to shadow branch '%s'\n", shadowBranchName)
	}

	// Log checkpoint creation
	logCtx := logging.WithComponent(context.Background(), "checkpoint")
	logging.Info(logCtx, "checkpoint saved",
		slog.String("strategy", "manual-commit"),
		slog.String("checkpoint_type", "session"),
		slog.Int("checkpoint_count", state.CheckpointCount),
		slog.Int("modified_files", len(ctx.ModifiedFiles)),
		slog.Int("new_files", len(ctx.NewFiles)),
		slog.Int("deleted_files", len(ctx.DeletedFiles)),
		slog.String("shadow_branch", shadowBranchName),
		slog.Bool("branch_created", !branchExisted),
	)

	return nil
}

// SaveTaskCheckpoint saves a task checkpoint to the shadow branch.
// Uses checkpoint.GitStore.WriteTemporaryTask for git operations.
func (s *ManualCommitStrategy) SaveTaskCheckpoint(ctx TaskCheckpointContext) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Load session state
	state, err := s.loadSessionState(ctx.SessionID)
	if err != nil || state == nil || state.BaseCommit == "" {
		// Initialize if needed (including if BaseCommit is empty from partial warning state)
		// Preserve existing AgentType if we have a partial state, otherwise use default
		agentType := DefaultAgentType
		if state != nil && state.AgentType != "" {
			agentType = state.AgentType
		}
		state, err = s.initializeSession(repo, ctx.SessionID, agentType, "") // No transcript path in fallback
		if err != nil {
			return fmt.Errorf("failed to initialize session for task checkpoint: %w", err)
		}
	}

	// Get checkpoint store
	store, err := s.getCheckpointStore()
	if err != nil {
		return fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Check if shadow branch exists to report whether we created it
	shadowBranchName := checkpoint.ShadowBranchNameForCommit(state.BaseCommit)
	branchExisted := store.ShadowBranchExists(state.BaseCommit)

	// Compute metadata paths for commit message
	sessionMetadataDir := paths.SessionMetadataDirFromEntireID(ctx.SessionID)
	taskMetadataDir := TaskMetadataDir(sessionMetadataDir, ctx.ToolUseID)

	// Generate commit message
	shortToolUseID := ctx.ToolUseID
	if len(shortToolUseID) > 12 {
		shortToolUseID = shortToolUseID[:12]
	}

	var messageSubject string
	if ctx.IsIncremental {
		messageSubject = FormatIncrementalSubject(
			ctx.IncrementalType,
			ctx.SubagentType,
			ctx.TaskDescription,
			ctx.TodoContent,
			ctx.IncrementalSequence,
			shortToolUseID,
		)
	} else {
		messageSubject = FormatSubagentEndMessage(ctx.SubagentType, ctx.TaskDescription, shortToolUseID)
	}
	commitMsg := trailers.FormatShadowTaskCommit(
		messageSubject,
		taskMetadataDir,
		ctx.SessionID,
	)

	// Use WriteTemporaryTask to create the checkpoint
	_, err = store.WriteTemporaryTask(context.Background(), checkpoint.WriteTemporaryTaskOptions{
		SessionID:              ctx.SessionID,
		BaseCommit:             state.BaseCommit,
		ToolUseID:              ctx.ToolUseID,
		AgentID:                ctx.AgentID,
		ModifiedFiles:          ctx.ModifiedFiles,
		NewFiles:               ctx.NewFiles,
		DeletedFiles:           ctx.DeletedFiles,
		TranscriptPath:         ctx.TranscriptPath,
		SubagentTranscriptPath: ctx.SubagentTranscriptPath,
		CheckpointUUID:         ctx.CheckpointUUID,
		CommitMessage:          commitMsg,
		AuthorName:             ctx.AuthorName,
		AuthorEmail:            ctx.AuthorEmail,
		IsIncremental:          ctx.IsIncremental,
		IncrementalSequence:    ctx.IncrementalSequence,
		IncrementalType:        ctx.IncrementalType,
		IncrementalData:        ctx.IncrementalData,
	})
	if err != nil {
		return fmt.Errorf("failed to write task checkpoint: %w", err)
	}

	// Track touched files (modified, new, and deleted)
	state.FilesTouched = mergeFilesTouched(state.FilesTouched, ctx.ModifiedFiles, ctx.NewFiles, ctx.DeletedFiles)

	// Save updated state
	if err := s.saveSessionState(state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}

	if !branchExisted {
		fmt.Fprintf(os.Stderr, "Created shadow branch '%s' and committed task checkpoint\n", shadowBranchName)
	} else {
		fmt.Fprintf(os.Stderr, "Committed task checkpoint to shadow branch '%s'\n", shadowBranchName)
	}

	// Log task checkpoint creation
	logCtx := logging.WithComponent(context.Background(), "checkpoint")
	attrs := []any{
		slog.String("strategy", "manual-commit"),
		slog.String("checkpoint_type", "task"),
		slog.String("checkpoint_uuid", ctx.CheckpointUUID),
		slog.String("tool_use_id", ctx.ToolUseID),
		slog.String("subagent_type", ctx.SubagentType),
		slog.Int("modified_files", len(ctx.ModifiedFiles)),
		slog.Int("new_files", len(ctx.NewFiles)),
		slog.Int("deleted_files", len(ctx.DeletedFiles)),
		slog.String("shadow_branch", shadowBranchName),
		slog.Bool("branch_created", !branchExisted),
	}
	if ctx.IsIncremental {
		attrs = append(attrs,
			slog.Bool("is_incremental", true),
			slog.String("incremental_type", ctx.IncrementalType),
			slog.Int("incremental_sequence", ctx.IncrementalSequence),
		)
	}
	logging.Info(logCtx, "task checkpoint saved", attrs...)

	return nil
}

// mergeFilesTouched merges multiple file lists into existing touched files, deduplicating.
func mergeFilesTouched(existing []string, fileLists ...[]string) []string {
	seen := make(map[string]bool)
	for _, f := range existing {
		seen[f] = true
	}

	for _, list := range fileLists {
		for _, f := range list {
			seen[f] = true
		}
	}

	result := make([]string, 0, len(seen))
	for f := range seen {
		result = append(result, f)
	}

	// Sort for deterministic output
	sort.Strings(result)
	return result
